namespace SmartWiFi {

  uint32_t lastAttemptMs = 0;
  const uint32_t RETRY_INTERVAL_MS = 10000;

  bool wasConnected = false;

  void begin() {

    WiFi.mode(WIFI_STA);
    WiFi.setAutoReconnect(true);

    Serial.print("Connecting WiFi: ");
    Serial.println(WIFI_SSID);

    WiFi.begin(
      WIFI_SSID,
      WIFI_PASSWORD
    );

    lastAttemptMs = millis();
  }

  void handle() {

    if (
      WiFi.status() == WL_CONNECTED
    ) {

      if (!wasConnected) {

        wasConnected = true;

        Serial.println("WiFi connected");

        Serial.print("IP: ");
        Serial.println(WiFi.localIP());
      }

      return;
    }

    if (wasConnected) {

      wasConnected = false;

      Serial.println("WiFi disconnected");
    }

    uint32_t now = millis();

    if (
      now - lastAttemptMs >=
      RETRY_INTERVAL_MS
    ) {

      lastAttemptMs = now;

      Serial.println(
        "WiFi reconnecting..."
      );

      WiFi.disconnect();
      WiFi.begin(
        WIFI_SSID,
        WIFI_PASSWORD
      );
    }
  }
}

