class BuzzerManager {

private:

  uint32_t lastToggle = 0;

  uint16_t onDuration = 0;
  uint16_t offDuration = 0;

  uint8_t remainingBeeps = 0;

  bool buzzerState = false;

public:

  void beep(
    uint8_t count,
    uint16_t onMs,
    uint16_t offMs
  ) {

    if (count == 0) {

      digitalWrite(
        BUZZER_PIN,
        LOW
      );

      remainingBeeps = 0;

      return;
    }

    remainingBeeps = count;

    onDuration = onMs;
    offDuration = offMs;

    buzzerState = true;

    lastToggle = millis();

    digitalWrite(
      BUZZER_PIN,
      HIGH
    );
  }

  void stop() {

    remainingBeeps = 0;

    buzzerState = false;

    digitalWrite(
      BUZZER_PIN,
      LOW
    );
  }

  void success() {
    beep(3, 100, 100);
  }

  void error() {
    beep(1, 800, 0);
  }

  void warning() {
    beep(5, 50, 50);
  }

  void tick() {
    beep(1, 50, 0);
  }

  void denied() {
    beep(2, 200, 100);
  }

  void update() {

    if (remainingBeeps == 0) {

      digitalWrite(
        BUZZER_PIN,
        LOW
      );

      return;
    }

    uint32_t now = millis();

    if (buzzerState) {

      if (
        now - lastToggle >=
        onDuration
      ) {

        buzzerState = false;

        digitalWrite(
          BUZZER_PIN,
          LOW
        );

        lastToggle = now;

        remainingBeeps--;

        if (
          remainingBeeps == 0
        ) {
          return;
        }
      }

      return;
    }

    if (
      remainingBeeps > 0 &&
      now - lastToggle >=
      offDuration
    ) {

      buzzerState = true;

      digitalWrite(
        BUZZER_PIN,
        HIGH
      );

      lastToggle = now;
    }
  }
};

