void saveQuickPlans() {

  char jsonBuf[1024];

  int offset =
    snprintf(
      jsonBuf,
      sizeof(jsonBuf),
      "{\"plans\":["
    );

  for (
    int i = 0;
    i < 4;
    i++
  ) {

    offset +=
      snprintf(
        jsonBuf + offset,
        sizeof(jsonBuf) - offset,

        "{\"id\":\"%s\","
        "\"title\":\"%s\","
        "\"dur\":%lu,"
        "\"allowStop\":%s,"
        "\"act\":%s}%s",

        activePlans[i].id,
        activePlans[i].title,

        (unsigned long)
        activePlans[i].durationSec,

        activePlans[i].allowStop
          ? "true"
          : "false",

        activePlans[i].active
          ? "true"
          : "false",

        (i < 3)
          ? ","
          : ""
      );
  }

  snprintf(
    jsonBuf + offset,
    sizeof(jsonBuf) - offset,
    "]}"
  );

  saveFileAtomic(
    "/quickplans.json",
    jsonBuf
  );
}

