void checkForBootRecovery() {

  if (
    !LittleFS.exists(
      "/active_session.json"
    )
  ) {

    return;
  }

  File f =
    LittleFS.open(
      "/active_session.json",
      FILE_READ
    );

  if (f) {

    char buf[256];

    size_t len =
      f.readBytes(
        buf,
        sizeof(buf) - 1
      );

    buf[len] =
      '\0';

    f.close();

    enforceStorageRetention(
      "/sessions.jsonl"
    );

    File sf =
      LittleFS.open(
        "/sessions.jsonl",
        FILE_APPEND
      );

    if (sf) {

      sf.println(buf);

      sf.close();
    }

    enforceStorageRetention(
      "/sync_queue.jsonl"
    );

    File qf =
      LittleFS.open(
        "/sync_queue.jsonl",
        FILE_APPEND
      );

    if (qf) {

      qf.println(buf);

      qf.close();
    }
  }

  LittleFS.remove(
    "/active_session.json"
  );
}

