// ============================================================
// SYNC QUEUE
// ============================================================

void processSyncQueue() {

  if (
    WiFi.status() !=
    WL_CONNECTED
  ) {
    return;
  }

  if (
    coreState !=
    CORE_IDLE
  ) {
    return;
  }

  if (
    !LittleFS.exists(
      "/sync_queue.jsonl"
    )
  ) {
    return;
  }

  File q =
    LittleFS.open(
      "/sync_queue.jsonl",
      FILE_READ
    );

  if (
    !q ||
    q.size() == 0
  ) {

    if (q) {
      q.close();
    }

    return;
  }

  bool allRecordsAcknowledged =
    true;

  char lineBuffer[256];

  size_t lineLen = 0;

  while (
    q.available()
  ) {

    char c =
      (char)q.read();

    if (
      c == '\n' ||
      c == '\r'
    ) {

      if (
        lineLen > 0
      ) {

        lineBuffer[lineLen] =
          '\0';

        if (
          !api_uploadSessionRecord(
            lineBuffer
          )
        ) {

          allRecordsAcknowledged =
            false;
        }

        lineLen = 0;
      }

    } else if (
      lineLen <
      sizeof(lineBuffer) - 1
    ) {

      lineBuffer[lineLen++] =
        c;
    }
  }

  if (
    lineLen > 0
  ) {

    lineBuffer[lineLen] =
      '\0';

    if (
      !api_uploadSessionRecord(
        lineBuffer
      )
    ) {

      allRecordsAcknowledged =
        false;
    }
  }

  q.close();

  if (
    allRecordsAcknowledged
  ) {

    LittleFS.remove(
      "/sync_queue.jsonl"
    );
  }
}

// ============================================================
// SENSOR MANAGER
// ============================================================

void updateSensors() {

  uint32_t now =
    millis();

  if (
    now - lastSensorTs <
    INTERVAL_SENSOR
  ) {

    return;
  }

  lastSensorTs =
    now;

  env.temp =
    dht.readTemperature();

  env.hum =
    dht.readHumidity();

  env.valid =
    !(
      isnan(env.temp) ||
      isnan(env.hum)
    );

  env.light =
    analogRead(
      LDR_PIN
    );

  env.aqRaw =
    analogRead(
      AQ_PIN
    );
}

