void updateButtons() {

  uint32_t now =
    millis();

  if (
    digitalRead(START_PIN) ==
    LOW &&
    now - lastStartBtn >=
    DEBOUNCE_MS
  ) {

    lastStartBtn =
      now;

    Serial.println(
      "START BUTTON"
    );

    buzzer.tick();
  }

  if (
    digitalRead(STOP_PIN) ==
    LOW &&
    now - lastStopBtn >=
    DEBOUNCE_MS
  ) {

    lastStopBtn =
      now;

    Serial.println(
      "STOP BUTTON"
    );

    buzzer.tick();
  }
}

