void setup() {

  Serial.begin(115200);

  Serial.println();
  Serial.println(
    "ROCKETG.O MAIN CONTROLLER"
  );

  pinMode(
    BUZZER_PIN,
    OUTPUT
  );

  pinMode(
    RGB_R_PIN,
    OUTPUT
  );

  pinMode(
    RGB_G_PIN,
    OUTPUT
  );

  pinMode(
    RGB_B_PIN,
    OUTPUT
  );

  digitalWrite(
    BUZZER_PIN,
    LOW
  );

  pinMode(
    START_PIN,
    INPUT_PULLUP
  );

  pinMode(
    STOP_PIN,
    INPUT_PULLUP
  );

  pinMode(
    TRIG_PIN,
    OUTPUT
  );

  pinMode(
    ECHO_PIN,
    INPUT
  );

  digitalWrite(
    TRIG_PIN,
    LOW
  );

  dht.begin();

  initStorage();

  SmartWiFi::begin();

  configTime(
    GMT_OFFSET,
    0,
    NTP_SERVER
  );

  coreState =
    CORE_IDLE;

  buzzer.success();

  Serial.println(
    "SYSTEM READY"
  );
}

// ============================================================
// LOOP
// ============================================================

void loop() {

  SmartWiFi::handle();

  buzzer.update();

  updateSensors();

  updateButtons();

  updateSystemHealth();

  updateTimeManager();

  uint32_t now =
    millis();

  if (
    now - lastSyncTs >=
    60000
  ) {

    lastSyncTs =
      now;

    processSyncQueue();
  }

  delay(1);
}
